use kni_core::generated_native;
pub use kni_core::{reference_slice,native_font,cff_container,ink_bounds};
use kni_core::native_font::NativeFontInput;
use kni_core::cff_container::CffGlyph;
use kni_core::reference_slice::{DrawnGlyph,ReferenceRing,Point,Span};
use kni_core::sfnt_metadata::{HeadMetadata,HheaMetadata,PostMetadata,Os2Metadata,NameRecord};
fn input()->NativeFontInput{
 let o=Point{x:0.,y:0.};
 let empty=CffGlyph{name:".notdef".into(),advance:500,outline:DrawnGlyph{glyph_id:"notdef".into(),rings:vec![]}};
 let a=CffGlyph{name:"A".into(),advance:500,outline:DrawnGlyph{glyph_id:"A".into(),rings:vec![ReferenceRing{start:o,spans:vec![Span::Line{end:Point{x:100.,y:0.}},Span::Cubic{control_one:Point{x:100.,y:100.},control_two:Point{x:0.,y:100.},end:o}]}]}};
 NativeFontInput{postscript_name:"Fixture-Regular".into(),glyphs:vec![empty,a],left_side_bearings:vec![0,0],mapping:vec![(65,1)],head:HeadMetadata{revision:0x10000,flags:0,units_per_em:1000,created:0,modified:0,bounds:[0,0,100,100],mac_style:0,lowest_ppem:1},hhea:HheaMetadata{ascender:800,descender:-200,line_gap:0,advance_max:500,min_lsb:0,min_rsb:400,max_extent:100,caret_rise:1,caret_run:0,caret_offset:0,metric_count:2},post:PostMetadata{italic_angle_fixed:0,underline_position:-100,underline_thickness:50,fixed_pitch:1,memory:[0;4]},os2:Os2Metadata{average_width:500,weight:400,width:5,embedding:2,subscript:[650,600,0,75],superscript:[650,600,0,350],strikeout:[50,300],family_class:0,panose:[0;10],unicode_ranges:[1,0,0,0],vendor:*b"TEST",selection:64,first_char:65,last_char:65,typo:[800,-200,0],win_ascent:800,win_descent:200,version:0,cap_height:0,x_height:0},names:[(1,"Fixture"),(2,"Regular"),(3,"Fixture:1"),(4,"Fixture Regular"),(5,"Version 1.0"),(6,"Fixture-Regular")].iter().map(|(id,text)|NameRecord{language:0x409,name_id:*id,value:text.to_string()}).collect()}
}
fn glyphs()->Vec<DrawnGlyph>{let i=input();let mut gs:Vec<_>=i.glyphs.iter().map(|g|g.outline.clone()).collect();gs[0].glyph_id=".notdef".into();gs}
fn metrics()->Vec<(String,f64,f64,f64)>{vec![(".notdef".into(),0.,500.,500.),("A".into(),20.,380.,500.)]}
#[test]fn export_and_derived_bounds(){let gs=glyphs();let i=generated_native::prepare_generated(&gs,&[(65,1)],&metrics(),&input()).unwrap();assert_eq!(i.head.bounds,[20,0,120,75]);assert_eq!(i.hhea.min_lsb,20);assert_eq!(i.hhea.min_rsb,380);assert_eq!(i.hhea.max_extent,120);assert_eq!(i.glyphs[1].outline.rings[0].start.x,20.);let bytes=generated_native::encode_generated(&gs,&[(65,1)],&metrics(),&input()).unwrap();assert_eq!(&bytes[..4],b"OTTO");assert_eq!(kni_core::cff_container::checksum(&bytes),0xb1b0afba);assert_eq!(gs[1].rings[0].start.x,0.);assert_eq!(i.postscript_name,"Fixture-Regular");}
#[test]fn negative_half_export(){let mut gs=glyphs();gs[1].rings[0].spans=vec![Span::Line{end:Point{x:100.,y:-0.5}},Span::Line{end:Point{x:0.,y:0.}}];let i=generated_native::prepare_generated(&gs,&[(65,1)],&metrics(),&input()).unwrap();match i.glyphs[1].outline.rings[0].spans[0]{Span::Line{end}=>assert_eq!(end.y,-1.),_=>panic!()}}
#[test]fn nonfinite_and_missing_metrics(){let mut gs=glyphs();gs[1].rings[0].start.x=f64::NAN;assert!(generated_native::prepare_generated(&gs,&[],&metrics(),&input()).is_err());assert!(generated_native::prepare_generated(&glyphs(),&[],&metrics()[..1],&input()).is_err());}
#[test]fn open_input_refuses_before_rounding(){let mut gs=glyphs();gs[1].rings[0].spans.pop();assert!(generated_native::prepare_generated(&gs,&[],&metrics(),&input()).is_err());}
#[test]fn duplicate_metric_and_glyph_refusal(){let gs=glyphs();let mut m=metrics();m.push(m[1].clone());assert!(generated_native::prepare_generated(&gs,&[],&m,&input()).is_err());let mut gs=gs;gs[1].glyph_id=".notdef".into();assert!(generated_native::prepare_generated(&gs,&[],&metrics(),&input()).is_err());}
#[test]fn cubic_ink_not_control_hull_shift(){let mut gs=glyphs();gs[1].rings[0].spans=vec![Span::Cubic{control_one:Point{x:-100.,y:10.},control_two:Point{x:-100.,y:20.},end:Point{x:0.,y:0.}}];let mut m=metrics();m[1].2=405.;let i=generated_native::prepare_generated(&gs,&[(65,1)],&m,&input()).unwrap();assert_eq!(i.glyphs[1].outline.rings[0].start.x,95.);assert!(i.head.bounds[0]>-5&&i.head.bounds[0]<=95);}

#[test]fn separate_ink_and_hull_no_continuous_gate(){let gs=glyphs();let mut m=metrics();m[1].2=1.;assert!(generated_native::prepare_generated(&gs,&[(65,1)],&m,&input()).is_ok());let m=metrics();let p=generated_native::prepare_generated(&gs,&[(65,1)],&m,&input()).unwrap();let rows=generated_native::rounding_ledger(&gs,&m,&p).unwrap();assert_eq!(rows[1].exported_hull_rsb,380.);assert_eq!(rows[1].input_identity_residual,0.);assert_eq!(rows[1].identity_rounding_bound,2.);}

#[test]fn fractional_requested_lsb_does_not_change_shape(){let gs=glyphs();let mut a=metrics();let mut b=metrics();a[1].1=0.;b[1].1=20.49;let ap=generated_native::prepare_generated(&gs,&[(65,1)],&a,&input()).unwrap();let bp=generated_native::prepare_generated(&gs,&[(65,1)],&b,&input()).unwrap();let ar=&ap.glyphs[1].outline.rings[0];let br=&bp.glyphs[1].outline.rings[0];assert_eq!(br.start.x-ar.start.x,20.);for(x,y)in ar.spans.iter().zip(&br.spans){match(x,y){(Span::Line{end:a},Span::Line{end:b})=>{assert_eq!(b.x-a.x,20.);assert_eq!(b.y,a.y)},(Span::Cubic{control_one:a,control_two:c,end:e},Span::Cubic{control_one:b,control_two:d,end:f})=>{for(p,q)in[(a,b),(c,d),(e,f)]{assert_eq!(q.x-p.x,20.);assert_eq!(q.y,p.y)}},_=>panic!()}}let ledger=generated_native::rounding_ledger(&gs,&b,&bp).unwrap();assert_eq!(ledger[1].actual_ink_lsb,20.);assert!((ledger[1].lsb_quantization+0.49).abs()<1e-12);}

#[test]fn ink_bounds_ignore_control_points_both_axes(){let mut gs=glyphs();gs[1].rings[0].spans=vec![Span::Cubic{control_one:Point{x:-100.,y:300.},control_two:Point{x:-100.,y:-300.},end:Point{x:0.,y:0.}}];let g=&gs[1];let b=generated_native::ink_min_x(g).unwrap().unwrap();assert!(b>-100.&&b<0.);let ib=kni_core::ink_bounds::integer_outward_bounds(g).unwrap().unwrap();assert!(ib[0]> -100&&ib[1]> -300&&ib[3]<300);assert!(ib[0]<=b.floor() as i16);}
#[test]fn head_bounds_equal_ink_not_hull_for_cubic(){let mut gs=glyphs();gs[1].rings[0].spans=vec![Span::Cubic{control_one:Point{x:-100.,y:10.},control_two:Point{x:-100.,y:20.},end:Point{x:0.,y:0.}}];let mut m=metrics();m[1].2=405.;let i=generated_native::prepare_generated(&gs,&[(65,1)],&m,&input()).unwrap();assert!(i.head.bounds[0]>-5);assert_eq!(i.hhea.min_lsb,i.head.bounds[0]);assert_eq!(i.left_side_bearings[1],i.head.bounds[0]);}
#[test]fn encode_requires_notdef_first(){let mut gs=glyphs();gs.swap(0,1);let r=generated_native::encode_generated(&gs,&[(65,1)],&metrics(),&input());assert!(matches!(r,Err(generated_native::GeneratedError::BadGlyphOrder)));}
#[test]fn encode_rejects_bad_mapping(){let gs=glyphs();assert!(matches!(generated_native::encode_generated(&gs,&[(65,9)],&metrics(),&input()),Err(generated_native::GeneratedError::BadMapping)));assert!(matches!(generated_native::encode_generated(&gs,&[(65,1),(65,0)],&metrics(),&input()),Err(generated_native::GeneratedError::BadMapping)));}
